// Aggregate sales data
const sales = items[0].json.transactions || [];
const totalRevenue = sales.reduce((sum, t) => sum + t.amount, 0);
const orderCount = sales.length;
const avgOrder = orderCount > 0 ? totalRevenue / orderCount : 0;
const topItems = {};
sales.forEach(t => {
  (t.items || []).forEach(i => {
    topItems[i.name] = (topItems[i.name] || 0) + (i.qty || 1);
  });
});
const sorted = Object.entries(topItems).sort((a, b) => b[1] - a[1]).slice(0, 5);
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    totalRevenue,
    orderCount,
    avgOrder,
    topItems: sorted
  }
}];

